import { createServer } from 'node:http';
import { createLinbikAuth, MemorySessionStore, isLinbikServerError } from '@linbik/paseto-auth-server';

const auth = createLinbikAuth({
  apiBaseUrl: 'https://api.linbik.com',
  apiKey: process.env.LINBIK_API_KEY,
  serviceId: process.env.LINBIK_SERVICE_ID,
  clientId: process.env.LINBIK_CLIENT_ID,
  sessionKey: process.env.LINBIK_SESSION_KEY,
  publicOrigin: 'http://localhost:5086',
  allowInsecureHttp: true, // yalnız loopback geliştirme
  store: new MemorySessionStore()
});

createServer(async (req, res) => {
  res.setHeader('Cache-Control', 'private, no-store');
  const cookies = [];
  const context = auth.createRequest({ cookieHeader: req.headers.cookie ?? '', onSetCookie: value => cookies.push(value) });
  const url = new URL(req.url, 'http://localhost:5086');
  const json = (status, body) => {
    res.writeHead(status, { 'Content-Type': 'application/json', 'Set-Cookie': cookies });
    res.end(JSON.stringify(body));
  };
  const redirect = location => { res.writeHead(302, { Location: location, 'Set-Cookie': cookies }); res.end(); };
  try {
    if (req.method === 'GET' && url.pathname === '/api/Linbik/login') {
      redirect(await context.signIn(url.searchParams.get('returnPath') ?? '/')); return;
    }
    if (req.method === 'GET' && url.pathname === '/api/Linbik/callback') {
      const result = await context.callback(url.searchParams.get('code'));
      redirect(result.returnPath); return;
    }
    if (req.method === 'GET' && url.pathname === '/api/Linbik/session') {
      const user = await context.getSession();
      json(user ? 200 : 401, user ? { isSuccess: true, data: user } : { isSuccess: false }); return;
    }
    if (req.method === 'POST' && ['/api/Linbik/refresh', '/api/Linbik/logout'].includes(url.pathname)) {
      const headers = new Headers();
      for (const name of ['origin', 'x-linbik-request']) if (typeof req.headers[name] === 'string') headers.set(name, req.headers[name]);
      auth.assertSameOrigin(headers);
      if (url.pathname.endsWith('/refresh')) json(200, { isSuccess: true, data: await context.refreshToken() });
      else { await context.signOut(); json(200, { isSuccess: true, data: null }); }
      return;
    }
    json(404, { isSuccess: false });
  } catch (error) {
    json(isLinbikServerError(error) ? error.status : 500, { isSuccess: false, friendlyMessage: { message: 'İstek tamamlanamadı.' } });
  }
}).listen(5086, '127.0.0.1');

