using Linbik.Core.Extensions;
using Linbik.PasetoAuthManager.Extensions;
using Linbik.Slices;
using Linbik.Slices.Generated;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddLinbik(builder.Configuration.GetSection("Linbik")).AddLinbikPasetoAuth();
builder.Services.AddLinbikSlices();
builder.Services.AddLinbikSliceExceptionHandling();
builder.Services.AddLinbikFlowDocuments();
var app = builder.Build();
app.EnsureLinbik();
app.UseLinbikSliceExceptionHandling();
app.UseRouting();
app.UseAuthentication();
app.UseAuthorization();
app.UseLinbikRateLimiting();
app.UseLinbikPasetoAuth();
app.MapLinbikSlices();
app.MapOpenApi();
app.Run();

using Linbik.Slices;
using Linbik.Slices.Results;

[LinbikSlice("/api/echo")]
[LAuthorizeFlow(LinbikFlow.Self)]
public static partial class Echo
{
    public sealed record Request(string Message) : ILinbikRequest<Response>;
    public sealed record Response(string Message);
    public sealed class Handler : ILinbikHandler<Request, Response>
    {
        public ValueTask<Result<Response>> HandleAsync(Request request, CancellationToken ct)
            => Result.Ok(new Response(request.Message)).AsValueTask();
    }
}

